def main():
    import sys

    class Payment:
        def __init__(self, amount):
            self.__amount = amount

        def getAmount(self):
            return self.__amount

        def calculateFinalAmount(self):
            pass

    class CreditCard(Payment):
        def calculateFinalAmount(self):
            return self.getAmount() * 1.02

    class UPI(Payment):
        def calculateFinalAmount(self):
            return self.getAmount() * 1.005

    class NetBanking(Payment):
        def calculateFinalAmount(self):
            return self.getAmount() + 10

    n = int(sys.stdin.readline().strip())
    total = 0

    for _ in range(n):
        payment_type, amount = map(int, sys.stdin.readline().split())

        if payment_type == 1:
            p = CreditCard(amount)
        elif payment_type == 2:
            p = UPI(amount)
        elif payment_type == 3:
            p = NetBanking(amount)

        final_amount = p.calculateFinalAmount()
        total += final_amount
        print("Final Amount: {:.2f}".format(final_amount))

    print("Total Processed Amount: {:.2f}".format(total))

if __name__ == "__main__":
    main()
